\documentclass{standalone} 
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usetikzlibrary{decorations.markings,decorations.pathmorphing}


\begin{document}
	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}	

	\begin{tikzpicture}
	\def\tstart{-2.5}			% in radians
	\def\tend{2.5}			% in radians
	\def\xr{2}		% x-radius
	\def\yr{2}		% y-radius

	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=none},
	axis line style = {-stealth, thick},
	axis equal,
	axis x line*=middle,
	axis y line*=middle,
	view={0}{90},
	xmin = -0.5, xmax=2.1, 
	ymin = -0.5, ymax=2.45,  
	xtick = {-10,10},
	ytick = {-10,10},
	%% Here, we can control the positioning of each individual tick.
	y tick label style={yshift={(\tick==2)*5pt}},
	y tick label style={yshift={(\tick==-2)*-5pt}},
	x tick label style={xshift={(\tick==2)*5pt}},
	x tick label style={xshift={(\tick==-2)*-7pt}}, 
	ticklabel style={outer sep=3pt} ,   
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={right, xshift = 0pt, yshift=0pt},
	ylabel style={above, xshift=0pt, yshift=0pt},
	every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)},anchor=south,}
	]

	\addplot3 [
	quiver= {u={x}, v={y^2}, scale arrows=0.09},
	gray, -stealth, color=gray, samples=15, opacity=0.75,
	%quiver/colored = {mapped color}, 
	domain = -0.9:2.5,
	domain y = -0.6:2.2,
	] {0};


% Unit vectors
\draw[-latex, very thick, orangepeel] (axis cs: {1},{1}) -- (axis cs: {1+1/sqrt(2)}, {1+1/sqrt(2)}) node [above, black] {$\mathbf{n}$};
\draw[-latex, very thick, fadedpink] (axis cs: {1},{1}) -- (axis cs: {1-1/sqrt(2)}, {1+1/sqrt(2)}) node[right, black] {$\mathbf{T}$};

% Curve C1
\plot[domain = {0.5}:{2},samples = 100,color = deepskyblue,line width = 1.2pt,
decoration={markings,mark=between positions 0.2 and 1 step 0.3 with {\arrow[]{>};}},
postaction={decorate}
]({1/(\x)},{\x});

%Rotation
\draw[->, thick] plot[domain=135:{133-88}] (axis cs:{0.2*cos(\x)+1},{0.2*sin(\x)+1}) node[above = 10 pt, right = -15 pt] {$90^\circ$};

\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs:0.5,2) {};
\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs:2,0.5) {};	



\end{axis}

	\end{tikzpicture}

	\end{document}

